scenario.en:
function retryUntilDone(job) {
  let attempts = 10;
  while (!job.done) {
    job.run();
    if (job.transient) continue;  // transient glitch: retry without counting
    attempts -= 1;
    if (attempts === 0) break;
  }
}

scenario.ru:
function retryUntilDone(job) {
  let attempts = 10;
  while (!job.done) {
    job.run();
    if (job.transient) continue;  // временный сбой: повторяем, не считая попытку
    attempts -= 1;
    if (attempts === 0) break;
  }
}
